import{_ as e}from"./chunks/vision_tasks.BzIM5FUo.js";import{_ as o,o as r,c as s,a0 as a}from"./chunks/framework.Ckbw5VQO.js";const m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/models/introduction.md","filePath":"guide/models/introduction.md"}'),i={name:"guide/models/introduction.md"};function n(d,t,l,c,h,p){return r(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>You can detect many things on an orthophoto, but not all are equally hard. Two factors decide feasibility: the <strong>availability of ready-made labels</strong> and the <strong>shape</strong> of the object.</p><ul><li>🟢 <code>Pools</code>: single colour, simple shape, few false positives</li><li>🟢 <code>Buildings</code>: free <a href="https://geoservices.ign.fr/bdtopo" target="_blank" rel="noreferrer">BD TOPO</a> labels</li><li>🟡 <code>Forests</code>: IGN BD Forêt labels, but complex polygon merging</li><li>🟠 <code>Isolated trees</code>: high zoom required, instances hard to separate</li><li>🔴 <code>Roads</code>: thin, long, occluded by trees</li></ul><div class="tip custom-block"><p class="custom-block-title">This project&#39;s choice</p><p><strong>Pools</strong> &amp; <strong>buildings</strong>: simple shapes and freely available labels (<a href="https://www.openstreetmap.org/" target="_blank" rel="noreferrer">OpenStreetMap</a> for pools, <a href="https://geoservices.ign.fr/bdtopo" target="_blank" rel="noreferrer">BD TOPO</a> for buildings).</p></div><h2 id="the-three-computer-vision-tasks" tabindex="-1">The three computer-vision tasks <a class="header-anchor" href="#the-three-computer-vision-tasks" aria-label="Permalink to &quot;The three computer-vision tasks&quot;">​</a></h2><p>Given an image, a model can answer three increasingly precise questions.</p><img src="'+e+'" style="display:block;margin:0 auto;width:100%;height:auto;"><table tabindex="0"><thead><tr><th>Task</th><th>Question</th><th>Output</th><th>Models</th></tr></thead><tbody><tr><td><strong>Classification</strong></td><td>What is in the image?</td><td>One answer for the whole image (&quot;it&#39;s a forest - 94%&quot;)</td><td>Classic CNN</td></tr><tr><td><strong>Object detection</strong></td><td>Where are the objects, and how many?</td><td>A bounding box around each object with a confidence score</td><td>YOLO, Faster R-CNN, SSD</td></tr><tr><td><strong>Segmentation</strong></td><td>Which class does each pixel belong to?</td><td>A class assigned to every pixel (&quot;this pixel = building, that one = water&quot;)</td><td>U-Net, SegFormer</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Choice: detection with <a href="https://docs.ultralytics.com/models/yolov8/" target="_blank" rel="noreferrer">YOLOv8</a></p><p>Detection is <strong>lighter</strong>, <strong>faster to train</strong>, and <strong>more reliable to export to ONNX</strong> for client-side inference.</p></div>',9)])])}const b=o(i,[["render",n]]);export{m as __pageData,b as default};
